import { createRouter, createWebHashHistory } from "vue-router";
import ListaDeputadosComponent from "@/components/ListaDeputadosComponent.vue";
import DetalheDeputadoComponent from "@/components/DetalheDeputadoComponent.vue";

const routes = [
  { path: "/", name: "lista", component: ListaDeputadosComponent },
  {
    path: "/deputado/:id",
    name: "detalhe",
    component: DetalheDeputadoComponent,
    props: true,
  },
];

export default createRouter({
  history: createWebHashHistory(),
  routes,
});
